// export default App;


function App() {
  const {setUser}=useContext(AuthContext);
  const {firebase}=useContext(FirebaseContext)
  useEffect(()=>{
    // console.log(user);
    firebase.auth().onAuthStateChanged((user)=>{
      setUser(user)
    })
    
  })
  return (
    <div>
      <Router>
        <Route exact path='/'>
          <Home />
        </Route>
        <Route path="/signup">
          <Signup />
        </Route>
        <Route path="/login">
          <Login />
        </Route>
      </Router>
    </div>
  );
}

export default App;
